    CONSTRAINT mandate_master_confidence_score_check CHECK (((confidence_score >= 0) AND (confidence_score <= 100))),
    CONSTRAINT mandate_master_investment_objective_check CHECK (((investment_objective)::text = ANY (ARRAY[('Growth'::character varying)::text, ('Income'::character varying)::text, ('Preservation'::character varying)::text, ('Balanced'::character varying)::text, ('Aggressive'::character varying)::text]))),
