    CONSTRAINT mandate_master_mandate_type_check CHECK (((mandate_type)::text = ANY (ARRAY[('Advisory'::character varying)::text, ('Discretionary'::character varying)::text, ('ModelDriven'::character varying)::text, ('NonDiscretionary'::character varying)::text]))),
    CONSTRAINT mandate_master_risk_tolerance_check CHECK (((risk_tolerance)::text = ANY (ARRAY[('Low'::character varying)::text, ('Medium'::character varying)::text, ('High'::character varying)::text, ('VeryHigh'::character varying)::text]))),
    CONSTRAINT mandate_master_time_horizon_check CHECK (((time_horizon)::text = ANY (ARRAY[('Short'::character varying)::text, ('Medium'::character varying)::text, ('Long'::character varying)::text, ('VeryLong'::character varying)::text])))
);

