    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    tenant_id uuid NOT NULL
);



--

-- Name: vol_surface_master; Type: TABLE; Schema: mdm; Owner: -
--

CREATE TABLE mdm.vol_surface_master (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    core_id uuid,
    underlier_security_id uuid NOT NULL,
    vol_surface_type character varying(50) NOT NULL,
    vol_as_of_date date NOT NULL,
    vol_source character varying(100) DEFAULT 'MarketDataVendor'::character varying NOT NULL,
    vol_grid jsonb DEFAULT '{}'::jsonb NOT NULL,
    vol_interpolation character varying(50) DEFAULT 'BiLinear'::character varying,
    vol_extrapolation character varying(50) DEFAULT 'Flat'::character varying,
    vol_confidence integer DEFAULT 80 NOT NULL,
    source_systems jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid DEFAULT '00000000-0000-0000-0000-000000000001'::uuid NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    CONSTRAINT vol_surface_master_vol_confidence_check CHECK (((vol_confidence >= 0) AND (vol_confidence <= 100))),
    CONSTRAINT vol_surface_master_vol_surface_type_check CHECK (((vol_surface_type)::text = ANY (ARRAY[('Equity'::character varying)::text, ('Rates'::character varying)::text, ('FX'::character varying)::text, ('Credit'::character varying)::text, ('Commodity'::character varying)::text, ('Other'::character varying)::text])))
);

ALTER TABLE ONLY mdm.vol_surface_master REPLICA IDENTITY FULL;


--

-- Name: vol_surface_point; Type: TABLE; Schema: mdm; Owner: -
--

CREATE TABLE mdm.vol_surface_point (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    surface_id uuid NOT NULL,
    surface_date date NOT NULL,
    surface_time timestamp with time zone,
    expiry_tenor character varying(30) NOT NULL,
    expiry_days integer,
    strike_type character varying(20) NOT NULL,
    strike_value numeric(24,12) NOT NULL,
    implied_vol numeric(20,12) NOT NULL,
    prior_implied_vol numeric(20,12),
    change_bps numeric(12,6),
    quality_tier_id uuid,
    is_stale boolean DEFAULT false NOT NULL,
    source_timestamp timestamp with time zone,
    custom_attributes jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    tenant_id uuid NOT NULL
);



